50	Status validate_utf8_name(std::string_view value, size_t max_bytes,
51	                          const char *prefix) {
52	  if (value.empty()) {
53	    return Status::InvalidArgument(prefix, " must not be empty");
54	  }
55	  if (value.size() > max_bytes) {
56	    return Status::InvalidArgument(prefix, "[", format_name(value),
57	                                   "] exceeds ", max_bytes, " bytes (got ",
58	                                   value.size(), ")");
59	  }
60	
61	  const auto *data = reinterpret_cast<const utf8proc_uint8_t *>(value.data());
62	  size_t position = 0;
63	  while (position < value.size()) {
64	    utf8proc_int32_t codepoint;
65	    auto bytes = utf8proc_iterate(
66	        data + position, static_cast<utf8proc_ssize_t>(value.size() - position),
67	        &codepoint);
