1650	Result<WriteResults> CollectionImpl::write_impl(std::vector<Doc> &docs,
1651	                                                WriteMode mode) {
1652	  CHECK_READONLY_RETURN_STATUS_EXPECTED();
1653	
1654	  std::shared_lock lock(schema_handle_mtx_);
1655	
1656	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
1657	  CHECK_CLOSED_RETURN_STATUS_EXPECTED(closed_, false);
1658	
1659	  for (auto &&doc : docs) {
1660	    auto s = doc.validate_and_sanitize(schema_, mode == WriteMode::UPDATE);
1661	    CHECK_RETURN_STATUS_EXPECTED(s);
1662	  }
1663	
1664	  // TODO: The granularity of the write_lock is too coarse.
1665	  std::lock_guard write_lock(write_mtx_);
1666	
1667	  WriteResults results;
1668	  // validate write batch size
1669	  if (docs.size() > kMaxWriteBatchSize) {
1670	    CHECK_RETURN_STATUS_EXPECTED(Status::InvalidArgument(
1671	        "Too many docs: ", docs.size(), " exceeds max write batch size of ",
1672	        kMaxWriteBatchSize));
1673	  }
1674	
1675	  for (auto &&doc : docs) {
1676	    if (need_switch_to_new_segment()) {
1677	      auto s = switch_to_new_segment_for_writing();
1678	      CHECK_RETURN_STATUS_EXPECTED(s);
1679	    }
1680	
1681	    Status s;
1682	
1683	    switch (mode) {
1684	      case WriteMode::UPSERT:
1685	        s = handle_upsert(doc);
1686	        break;
1687	      case WriteMode::UPDATE:
1688	        s = handle_update(doc);
1689	        break;
1690	      case WriteMode::INSERT:
1691	        s = handle_insert(doc);
1692	        break;
1693	      default:
1694	        s = Status::InvalidArgument("Invalid write mode");
1695	    }
1696	
1697	    results.push_back(s);
1698	  }
1699	
1700	  return results;
1701	}
