1703	bool CollectionImpl::need_switch_to_new_segment() const {
1704	  return writing_segment_->doc_count() >= schema_->max_doc_count_per_segment();
1705	}
1706	
1707	Status CollectionImpl::commit_schema_change_with_new_writing_segment(
1708	    const CollectionSchema::Ptr &new_schema,
1709	    const Segment::Ptr &old_writing_segment, const Version &old_version,
1710	    Version *new_version, uint64_t writing_min_doc_id) {
1711	  if (new_version == nullptr) {
1712	    return Status::InvalidArgument("new_version is null");
1713	  }
1714	
1715	  auto seg_options =
1716	      SegmentOptions{false, options_.enable_mmap_, options_.max_buffer_size_};
1717	  auto new_writing_segment = Segment::CreateAndOpen(
1718	      path_, *new_schema, allocate_segment_id(), writing_min_doc_id, id_map_,
1719	      delete_store_, version_manager_, seg_options);
1720	  if (!new_writing_segment) {
1721	    return new_writing_segment.error();
1722	  }
1723	  new_version->reset_writing_segment_meta(new_writing_segment.value()->meta());
1724	  new_version->set_next_segment_id(segment_id_allocator_.load());
1725	
1726	  auto s = version_manager_->apply(*new_version);
1727	  if (!s.ok()) {
1728	    new_writing_segment.value()->destroy();
1729	    return s;
1730	  }
1731	
1732	  s = version_manager_->flush();
1733	  if (!s.ok()) {
1734	    new_writing_segment.value()->destroy();
1735	    auto rollback_status = version_manager_->apply(old_version);
1736	    CHECK_RETURN_STATUS(rollback_status);
1737	    return s;
1738	  }
1739	
1740	  schema_ = new_schema;
1741	  writing_segment_ = new_writing_segment.value();
1742	  s = old_writing_segment->destroy();
1743	  CHECK_RETURN_STATUS(s);
1744	
1745	  return Status::OK();
1746	}
1747	
1748	Status CollectionImpl::switch_to_new_segment_for_writing(
1749	    const CollectionSchema::Ptr &schema) {
1750	  if (writing_segment_->doc_count() == 0) {
1751	    return writing_segment_->flush();
1752	  }
1753	
1754	  auto s = writing_segment_->dump();
1755	  CHECK_RETURN_STATUS(s);
1756	
1757	  s = segment_manager_->add_segment(writing_segment_);
1758	  CHECK_RETURN_STATUS(s);
1759	
1760	  // when create new segment, segment meta should create a first new block
1761	  // meta
1762	  auto new_segment = Segment::CreateAndOpen(
1763	      path_, schema == nullptr ? *schema_ : *schema, allocate_segment_id(),
1764	      writing_segment_->meta()->max_doc_id() + 1, id_map_, delete_store_,
1765	      version_manager_,
1766	      SegmentOptions{false, options_.enable_mmap_, options_.max_buffer_size_});
1767	  if (!new_segment) {
1768	    return new_segment.error();
1769	  }
1770	
1771	  Version version = version_manager_->get_current_version();
1772	  auto writing_segment_meta = writing_segment_->meta();
1773	  writing_segment_->remove_writing_forward_block();
1774	  s = version.add_persisted_segment_meta(writing_segment_meta);
1775	  CHECK_RETURN_STATUS(s);
1776	
1777	  writing_segment_ = new_segment.value();
1778	  version.reset_writing_segment_meta(writing_segment_->meta());
1779	  version.set_next_segment_id(segment_id_allocator_.load());
1780	
1781	  s = version_manager_->apply(version);
1782	  CHECK_RETURN_STATUS(s);
1783	  s = version_manager_->flush();
1784	  CHECK_RETURN_STATUS(s);
1785	
1786	  return Status::OK();
1787	}
